#!/usr/bin/env bash
# Build the Rust bridge for the Swift package: release static archives for
# both Apple targets, Swift/C bindings generated by the app-owned UniFFI
# generator, one universal archive and the GliffCoreFFI XCFramework.
#
# Outputs (ignored by Git):
#   macos/Packages/GliffCore/Artifacts/GliffCoreFFI.xcframework
#   macos/Packages/GliffCore/Artifacts/provenance.json
#   macos/Packages/GliffCore/Sources/GliffCore/Generated/GliffCore.swift
# Intermediate files live under build/bridge/. Run it before resolving the
# GliffCore package (swift build/test, Xcode) and after any change to the
# bridge crates, uniffi.toml, the lockfile or the toolchain.
set -euo pipefail
source "$(dirname "$0")/lib.sh"
cd "$GLIFF_ROOT"
require_command cargo
require_macos
require_command lipo
require_command otool

export MACOSX_DEPLOYMENT_TARGET=13.0
targets=(aarch64-apple-darwin x86_64-apple-darwin)
package=macos/Packages/GliffCore
artifacts="$package/Artifacts"
generated="$package/Sources/GliffCore/Generated"
out=build/bridge
lib=libgliff_mac_core.a

rm -rf "$out"
mkdir -p "$out/headers" "$out/universal"

for target in "${targets[@]}"; do
  printf '==> Building gliff-mac-core for %s\n' "$target"
  cargo build --locked --release --target "$target" -p gliff-mac-core
done
cargo build --locked --release -p gliff-uniffi-bindgen
bindgen=target/release/gliff-uniffi-bindgen

# Generate from each slice: the bindings must not depend on the architecture.
for target in "${targets[@]}"; do
  "$bindgen" generate --library "target/$target/release/$lib" --language swift \
    --config uniffi.toml --out-dir "$out/generated-$target" > /dev/null
done
if ! diff -r "$out/generated-${targets[0]}" "$out/generated-${targets[1]}" > /dev/null; then
  printf 'Generated bindings differ between %s and %s\n' "${targets[@]}" >&2
  exit 1
fi
gen="$out/generated-${targets[0]}"

lipo -create \
  "target/${targets[0]}/release/$lib" "target/${targets[1]}/release/$lib" \
  -output "$out/universal/$lib"
archs="$(lipo -archs "$out/universal/$lib")"
[[ "$archs" == "x86_64 arm64" || "$archs" == "arm64 x86_64" ]] \
  || { printf 'Unexpected universal slices: %s\n' "$archs" >&2; exit 1; }
# Our objects target the deployment version; Rust's prebuilt compiler_builtins
# objects target an older one (arm64: 11.0). None may require a newer macOS.
minos="$(otool -l "$out/universal/$lib" | awk '/LC_BUILD_VERSION/{b=1} b&&/minos/{print $2; b=0}' | sort -uV)"
[[ "$(tail -1 <<< "$minos")" == "$MACOSX_DEPLOYMENT_TARGET" ]] \
  || { printf 'Objects target macOS %s, expected at most %s\n' "$(tr '\n' ' ' <<< "$minos")" \
         "$MACOSX_DEPLOYMENT_TARGET" >&2; exit 1; }

# SwiftPM and Xcode look for module.modulemap next to the header.
cp "$gen/GliffCoreFFI.h" "$out/headers/"
cp "$gen/GliffCoreFFI.modulemap" "$out/headers/module.modulemap"

rm -rf "$artifacts" "$generated"
mkdir -p "$artifacts" "$generated"
xcodebuild -create-xcframework \
  -library "$out/universal/$lib" -headers "$out/headers" \
  -output "$artifacts/GliffCoreFFI.xcframework" > /dev/null
cp "$gen/GliffCore.swift" "$generated/GliffCore.swift"

sha() { shasum -a 256 "$1" | cut -d' ' -f1; }
uniffi="$(awk '/^name = "uniffi"$/{getline; print $3}' Cargo.lock | tr -d '"')"
dirty=false
git diff --quiet HEAD -- crates tools Cargo.toml Cargo.lock uniffi.toml || dirty=true
cat > "$artifacts/provenance.json" <<EOF
{
  "source_sha": "$(git rev-parse HEAD)",
  "source_dirty": $dirty,
  "upstream_revision": "$(cat upstream-revision)",
  "rustc": "$(rustc --version)",
  "uniffi": "$uniffi",
  "xcode": "$(xcodebuild -version | tr '\n' ' ' | sed 's/ *$//')",
  "deployment_target": "$MACOSX_DEPLOYMENT_TARGET",
  "slices": "$archs",
  "universal_archive_sha256": "$(sha "$out/universal/$lib")",
  "swift_bindings_sha256": "$(sha "$generated/GliffCore.swift")",
  "c_header_sha256": "$(sha "$out/headers/GliffCoreFFI.h")"
}
EOF
printf 'Bridge ready: %s (%s), bindings %s\n' "$artifacts/GliffCoreFFI.xcframework" "$archs" "$generated"
